#!/usr/bin/env bash
set -eu
python3 - <<'PY'
import csv
from pathlib import Path

def rows(name):
    with Path(name).open(encoding='utf-8', newline='') as stream:
        return list(csv.DictReader(stream, delimiter='\t'))

regions = {r['region']: r for r in rows('deploy/regions.tsv')}
for target in rows('deploy/targets.tsv'):
    if target['enabled'] != 'yes':
        continue
    path = Path(target['path'])
    original = path.read_bytes()
    Path(str(path) + '.bak').write_bytes(original)
    region = regions[target['region']]
    port = int(region['base_port']) + int(target['shard'])
    section = None
    result = []
    for line in original.decode('utf-8').splitlines(keepends=True):
        if line.startswith('[') and line.rstrip('\r\n').endswith(']'):
            section = line.rstrip('\r\n')
        if section == '[worker]':
            if line.startswith('port='):
                line = f'port={port}\n'
            elif line.startswith('endpoint='):
                line = f"endpoint={region['endpoint']}\n"
        result.append(line)
    path.write_bytes(''.join(result).encode('utf-8'))
PY
